fn base_str(&self, nullable: bool, refers: Reference) -> &str {
    let (string, bytes) = if refers == Reference::Own || (refers == Reference::Mut && nullable)
    {
        ("String", "Vec<u8>")
    } else {
        ("str", "[u8]")
    };

    match self {
        Self::Bool => "bool",
        Self::U8 => "u8",
        Self::I8 => "i8",
        Self::I16 => "i16",
        Self::I32 => "i32",
        Self::I64 => "i64",
        Self::F32 => "f32",
        Self::F64 => "f64",
        Self::String => string,
        Self::_Bytes => bytes,
        Self::Custom(s) => s.as_pascal_case(),
    }
